public static File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("dir cannot be null");
    if (name == null) throw new IllegalArgumentException("name cannot be null");
    // Strip query part after '?'
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Remove any leading path separators or drive letters, normalize separators
    // Use Paths.get(name).normalize()
    Path normalized = Paths.get(name).normalize();
    // Ensure no ".." components remain after normalization that would escape dir
    // Also ensure the normalized path is a single file name (no parent directories)
    if (normalized.getNameCount() != 1) {
        // If there are directories, take only the file name part
        normalized = normalized.getFileName();
    }
    String safeName = normalized.toString();

    // Additional check: ensure safeName does not contain separator characters after conversion
    if (safeName.contains("/") || safeName.contains("\\") || safeName.contains("..")) {
        throw new IllegalArgumentException("Invalid file name");
    }

    // Build file
    File file = new File(dir, safeName);
    // Ensure file is within dir after canonical resolution
    try {
        File canonicalDir = dir.getCanonicalFile();
        File canonicalFile = file.getCanonicalFile();
        if (!canonicalFile.getPath().startsWith(canonicalDir.getPath() + File.separator)) {
            throw new IllegalArgumentException("Resulting file is outside the target directory");
        }
    } catch (IOException e) {
        throw new RuntimeException("Failed to resolve canonical paths", e);
    }

    // Determine prefix/suffix for duplicate handling
    int dot = safeName.lastIndexOf('.');
    String prefix = dot < 0 ? safeName : safeName.substring(0, dot);
    String suffix = dot < 0 ? "" : safeName.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }
    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }
    return file;
}

