    if (domAssertionCount != assertions.size()) {
        LOG.fine("Number of Assertion elements in the DOM does not match the unmarshalled list – possible wrapping attack");
        throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
    }

    Set<String> assertionIds = new HashSet<>();
    boolean foundValidSubject = false;
    Date sessionNotOnOrAfter = null;

    for (Assertion assertion : assertions) {
        // Unique ID check
        String assertionId = assertion.getID();
        if (assertionId == null || assertionId.isEmpty()) {
            LOG.fine("Assertion ID must be present");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }
        if (!assertionIds.add(assertionId)) {
            LOG.fine("Duplicate Assertion ID detected – possible wrapping attack");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

        // Issuer validation
        if (assertion.getIssuer() == null) {
            LOG.fine("Assertion Issuer must not be null");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }
        validateIssuer(assertion.getIssuer());

        // Signature validation
        if (assertion.isSigned()) {
            verifySignature(assertion.getSignature(), assertionId, "Assertion");
        } else if (enforceAssertionsSigned && postBinding) {
            LOG.fine("If the HTTP Post binding is used to deliver the Response, the enclosed assertions must be signed");
            throw new WSSecurityException(WSSecurityException.ErrorCode.FAILURE, "invalidSAMLsecurity");
        }

