            int repeatCount = n & 0x7f;
            int value = in.read();
            if (value == -1) {
                throw new EOFException("Unexpected end of compressed data while reading repeat value");
            }
            // limit repeatCount to remaining space to avoid ArrayIndexOutOfBounds
            int toWrite = Math.min(repeatCount, total - position);
            for (int i = 0; i < toWrite; i++) {
