    protected final Pattern allowedActionNames = Pattern.compile("[a-zA-Z0-9._!/\\-]*");

    // other methods ...

    /**
     * Validates and sanitises an action name extracted from the request URI.
     *
     * <p>If the supplied {@code rawActionName} consists solely of characters
     * permitted by {@link #allowedActionNames}, it is returned unchanged.
     * Otherwise the method logs a warning and returns an empty string,
     * signalling that the action name is not acceptable.
     *
