     * @return a safe action name – either the original value (if valid) or an empty string
     */
    protected String cleanupActionName(final String rawActionName) {
        // Defensive null‑check – a null name cannot be valid.
        if (rawActionName == null) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received a null action name; treating as invalid.");
            }
            return "";
        }

        // Validate the whole string against the whitelist pattern.
        if (allowedActionNames.matcher(rawActionName).matches()) {
            return rawActionName;
        }

        // The name contains disallowed characters – reject it.
        if (LOG.isWarnEnabled()) {
            LOG.warn(
                "Action/method [{0}] does not match allowed action names pattern [{1}]; rejecting it.",
                rawActionName,
                allowedActionNames.pattern()
