private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Validate arguments
    if (buffer == null) {
        throw new NullPointerException("buffer");
    }
    if (offset < 0 || length < 0 || offset + length > buffer.length) {
        throw new IndexOutOfBoundsException("Invalid offset/length");
    }
    if (length == 0) {
        return 0;
    }

    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    long entrySize = current.entry.getSize();
    // If size is unknown or negative, treat as EOF after stream ends
    if (entrySize < 0) {
        // fallback to stream read until EOF
        return readUntilEof(buffer, offset, length);
    }

    // Guard against overflow when casting to int later
    if (entrySize > Integer.MAX_VALUE) {
        // Limit to Integer.MAX_VALUE to avoid overflow; we will read in chunks
        // but keep entrySize as long for calculations.
    }

    // If we have already read the declared size, signal EOF
    if (current.bytesRead >= entrySize) {
        return -1;
    }

    // Ensure buffer has data
    if (buf.position() >= buf.limit()) {
        buf.clear(); // position=0, limit=capacity
        int read = in.read(buf.array());
        if (read == -1) {
            // Unexpected EOF before declared size; treat as EOF
            return -1;
        }
        buf.limit(read);
        count(read);
        current.bytesReadFromStream += read;
    }

    // Determine how many bytes we can safely return
    int maxFromBuf = buf.remaining();
    int maxFromEntry = (int) Math.min(entrySize - current.bytesRead, Integer.MAX_VALUE);
    int toRead = Math.min(Math.min(maxFromBuf, length), maxFromEntry);

    if (toRead <= 0) {
        // No data available, but we haven't reached declared size.
        // This can happen if the underlying stream returned 0 bytes.
        // Return -1 to avoid infinite loop.
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
