import java.util.Calendar;
import java.util.logging.Level;
import java.util.logging.Logger;
import static java.util.Calendar.*;

public final class CronTab {

    private static final Logger LOGGER = Logger.getLogger(CronTab.class.getName());

    // other methods …

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it indicates an impossible
     * (e.g. Jun 31) date, or at least a date too rare to be useful. This addresses JENKINS-41864 and was added in 2.49
     */
    public Calendar ceil(Calendar cal) {
        // two‑year limit – used to detect dates that are “too rare”
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        // safeguard against an infinite loop – the algorithm should converge well before this limit
        final int MAX_ITERATIONS = 1_000;          // generous but finite
        int iteration = 0;

        OUTER:
        while (true) {
            // defensive: abort if we have iterated far too many times
            if (iteration++ > MAX_ITERATIONS) {
                LOGGER.log(Level.WARNING,
                        "Ceil algorithm exceeded max iterations ({0}) for calendar {1}",
                        new Object[]{MAX_ITERATIONS, cal.getTime()});
                throw new RareOrImpossibleDateException(
                        "Ceil algorithm did not converge after " + MAX_ITERATIONS + " iterations");
            }

            // abort if we have walked past the two‑year horizon
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // walk through the fields in the defined adjustment order
            for (CalendarField f : CalendarField.ADJUST_ORDER) {

                int cur = f.valueOf(cal);
                int next = f.ceil(this, cur);

                // already at the ceiling – nothing to do for this field
                if (cur == next) {
                    continue;
                }

                // any change to a higher field must clear all lower fields
                for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                    l.clear(cal);
                }

                if (next < 0) {
                    // no valid value for this field – roll it up and start over
                    f.rollUp(cal, 1);
                    f.setTo(cal, f.first(this));
                    continue OUTER;
                } else {
                    // set to the next valid value
                    f.setTo(cal, next);

                    // some fields require a full re‑evaluation after being modified
                    if (f.redoAdjustmentIfModified) {
                        continue OUTER;
                    }
                }
            }

            // all fields satisfied – return the adjusted calendar
            return cal;
        }
    }

    // other methods …

}
