import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.apache.camel.Exchange;
import org.apache.camel.Expression;
import org.apache.camel.NoTypeConversionAvailableException;
import org.apache.camel.Predicate;
import org.apache.camel.WrappedFile;
import org.apache.camel.component.bean.BeanInvocation;
import org.apache.camel.spi.NamespaceAware;
import org.apache.camel.support.ServiceSupport;

public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Secure XML parsing helpers
    // -------------------------------------------------------------------------

    /**
     * Parses the supplied {@link InputStream} into a {@link Document} while
     * disabling all features that could lead to XML External Entity (XXE)
     * attacks.
     *
     * @param is the XML input stream
     * @return a securely parsed {@link Document}
     * @throws Exception if the XML cannot be parsed
     */
    private Document parseXmlSecurely(InputStream is) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // ---- Secure configuration (prevent XXE) -------------------------
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Disallow DOCTYPE declarations
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disable external entities
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // Do not allow XInclude
        dbf.setXIncludeAware(false);
        // Do not expand entity references
        dbf.setExpandEntityReferences(false);
        // -------------------------------------------------------------------

        DocumentBuilder db = dbf.newDocumentBuilder();
        return db.parse(is);
    }

    // -------------------------------------------------------------------------
    // Original logic (patched for security)
    // -------------------------------------------------------------------------

    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Class<?> type = getDocumentType();
        Exception cause = null;

        // -----------------------------------------------------------------
        // If the caller expects a DOM Document (the default), parse the XML
        // securely and return the Document instance.
        // -----------------------------------------------------------------
        if (type != null && Document.class.isAssignableFrom(type)) {
            // Already a Document – nothing to do.
            if (body instanceof Document) {
                return body;
            }

            // Try to obtain an InputStream for the XML payload.
            InputStream is = null;
            try {
                if (body instanceof InputStream) {
                    is = (InputStream) body;
                } else if (body instanceof String) {
                    is = new ByteArrayInputStream(((String) body).getBytes(StandardCharsets.UTF_8));
                } else if (body instanceof WrappedFile) {
                    is = exchange.getContext().getTypeConverter()
                                 .convertTo(InputStream.class, exchange, body);
                } else {
                    // Fallback to Camel's type converter for any other type.
                    is = exchange.getContext().getTypeConverter()
                                 .convertTo(InputStream.class, exchange, body);
                }

                if (is != null) {
                    // Parse securely and return the Document.
                    try (InputStream autoClose = is) {
                        return parseXmlSecurely(autoClose);
                    }
                }
            } catch (Exception e) {
                // Remember the cause – we will re‑throw it later if we cannot
                // produce a result.
                cause = e;
            }
        }

        // -----------------------------------------------------------------
        // Fallback to the original behaviour for non‑Document types.
        // The original code returned an InputSource for String/Stream which
        // could be parsed later by an insecure parser.  To avoid re‑introducing
        // the XXE risk we now return the raw payload (String or InputStream)
        // when the caller does not explicitly request a Document.
        // -----------------------------------------------------------------
        Object answer = null;
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e;
            }
        }

        if (answer == null) {
            if (body instanceof WrappedFile) {
                // Return the raw InputStream – the caller can decide how to handle it.
                answer = exchange.getContext().getTypeConverter()
                                 .convertTo(InputStream.class, exchange, body);
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext().getTypeConverter()
                                            .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                // Return the original String instead of an InputSource.
                answer = body;
            }
        }

        // If no specific type was requested and we still have no answer,
        // fall back to returning the original body.
        if (type == null && answer == null) {
            answer = body;
        } else if (answer == null) {
            // Propagate the original conversion problem.
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // other methods ...

}
