public final class VersionUtil {

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Safely compares two version strings.
     * <p>
     * The method accepts version strings in the form {@code "major.minor.patch"},
     * but it is tolerant to malformed input:
     * <ul>
     *   <li>If a version string is {@code null} or empty it is treated as {@code "0.0.0"}.</li>
     *   <li>Missing components are considered {@code 0} (e.g. {@code "1"} → {@code 1.0.0}).</li>
     *   <li>Non‑numeric components are also treated as {@code 0} instead of throwing an exception.</li>
     * </ul>
     * This defensive approach prevents {@code ArrayIndexOutOfBoundsException}
     * and {@code NumberFormatException} that could otherwise be triggered by
     * attacker‑controlled input, eliminating a potential denial‑of‑service
     * vector.
     *
     * @param fromVersion the initial version (may be {@code null} or malformed)
     * @param toVersion   the target version (may be {@code null} or malformed)
     * @return a negative integer, zero, or a positive integer as {@code fromVersion}
     *         is less than, equal to, or greater than {@code toVersion}.
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        // Normalise null values to empty strings to avoid NPEs.
        if (fromVersion == null) {
            fromVersion = "";
        }
        if (toVersion == null) {
            toVersion = "";
        }

        // Trim whitespace and split on the literal dot.
        String[] fromArr = fromVersion.trim().split("\\.");
        String[] toArr   = toVersion.trim().split("\\.");

        // Parse each component safely; missing or non‑numeric parts become 0.
        int fromMajor = parseComponent(fromArr, 0);
        int fromMinor = parseComponent(fromArr, 1);
        int fromPatch = parseComponent(fromArr, 2);

        int toMajor = parseComponent(toArr, 0);
        int toMinor = parseComponent(toArr, 1);
        int toPatch = parseComponent(toArr, 2);

        // Compare major, then minor, then patch.
        if (fromMajor != toMajor) {
            return fromMajor - toMajor;
        }
        if (fromMinor != toMinor) {
            return fromMinor - toMinor;
        }
        return fromPatch - toPatch;
    }

    /**
     * Parses a numeric component from a split version array.
     *
     * @param parts the array obtained from {@code String.split("\\.")}.
     * @param index the component index to read (0 = major, 1 = minor, 2 = patch).
     * @return the integer value of the component, or {@code 0} if the component
     *         is missing or cannot be parsed as an integer.
     */
    private static int parseComponent(String[] parts, int index) {
        if (parts.length > index) {
            try {
                return Integer.parseInt(parts[index]);
            } catch (NumberFormatException ignored) {
                // Invalid numeric component – treat as 0.
            }
        }
        return 0;
    }

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------
}
