import com.thoughtworks.xstream.converters.UnmarshallingContext;

/**
 * Hardened XStream implementation.
 *
 * <p>
 * The original implementation allowed the deserialization of {@code void} /
 * {@code java.lang.Void} types.  When such a type is encountered XStream would
 * try to instantiate it, which leads to a JVM crash (SECURITY‑247).  The fix
 * consists of two parts:
 *
 * <ul>
 *   <li>Explicitly deny {@code Void.class} and {@code Void.TYPE} via XStream's
 *       permission API.</li>
 *   <li>Register a high‑priority {@link VoidTypeConverter} that rejects any
 *       attempt to (un)marshal these types before the default reflection‑based
 *       converters get a chance to handle them.</li>
 * </ul>
 *
 * Both measures guarantee that even if a future XStream version adds a new
 * converter for {@code void}, the denial will still be enforced.
 */
public class XStream2 extends XStream {

    // ----------------------------------------------------------------------
    //  Initialization
    // ----------------------------------------------------------------------
    private void init() {

        // ------------------------------------------------------------------
        //  1.  Harden the security model – deny Void types completely.
        // ------------------------------------------------------------------
        // Void.class  -> java.lang.Void (reference type)
        // Void.TYPE   -> void (primitive type, represented as a Class object)
        denyTypes(new Class[] { Void.class, Void.TYPE });

        // ------------------------------------------------------------------
        //  2.  Register converters.
        // ------------------------------------------------------------------
        // Types that should be marshalled out like a value, without referential
        // integrity tracking.
        addImmutableType(Result.class);

        registerConverter(new RobustCollectionConverter(getMapper(), getReflectionProvider()), 10);
        registerConverter(new RobustMapConverter(getMapper()), 10);
        registerConverter(new ImmutableMapConverter(getMapper(), getReflectionProvider()), 10);
        registerConverter(new ImmutableSortedSetConverter(getMapper(), getReflectionProvider()), 10);
        registerConverter(new ImmutableSetConverter(getMapper(), getReflectionProvider()), 10);
        registerConverter(new ImmutableListConverter(getMapper(), getReflectionProvider()), 10);
        registerConverter(new ConcurrentHashMapConverter(getMapper(), getReflectionProvider()), 10);
        registerConverter(new CopyOnWriteMap.Tree.ConverterImpl(getMapper()), 10); // needs to override MapConverter
        registerConverter(new DescribableList.ConverterImpl(getMapper()), 10);      // explicitly added to handle subtypes
        registerConverter(new Label.ConverterImpl(), 10);

        // This should come after all the XStream's default simpler converters,
        // but before reflection‑based one kicks in.
        registerConverter(new AssociatedConverterImpl(this), -10);

        // ------------------------------------------------------------------
        //  3.  SECURITY‑247 – block black‑listed types.
        // ------------------------------------------------------------------
        registerConverter(new BlacklistedTypesConverter(), PRIORITY_VERY_HIGH);

        // ------------------------------------------------------------------
        //  4.  SECURITY‑105 – block dynamic proxies.
        // ------------------------------------------------------------------
        registerConverter(new DynamicProxyConverter(getMapper()) { // SECURITY‑105 defense

