    /** Whitelisted component classes that are considered safe for deserialization. */
    private static final Set<Class<?>> ALLOWED_COMPONENT_TYPES = new HashSet<>(Arrays.asList(
            Boolean.class, Byte.class, Short.class, Integer.class, Long.class,
            Float.class, Double.class, Character.class, String.class,
            BigDecimal.class, BigInteger.class,
            Date.class, LocalDate.class, LocalDateTime.class, Instant.class
