    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        // -----------------------------------------------------------------
        // 1. Defensive Fastjson configuration – turn off auto‑type support.
        // -----------------------------------------------------------------
        parser.getConfig().setAutoTypeSupport(false);   // disables the vulnerable feature
        parser.getConfig().setSafeMode(true);          // extra safety checks introduced in newer Fastjson versions

        // -----------------------------------------------------------------
        // 2. Basic token handling (null and string literals).
        // -----------------------------------------------------------------
        final JSONLexer lexer = parser.lexer;

        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        if (lexer.token() == JSONToken.LITERAL_STRING) {
            // Fastjson provides the raw bytes of the string literal – keep original behaviour.
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

        // -----------------------------------------------------------------
        // 3. Resolve the component class of the target array.
        // -----------------------------------------------------------------
        Class<?> componentClass;

        if (type instanceof GenericArrayType) {
            // For generic array types we simply obtain the raw component type.
            GenericArrayType gat = (GenericArrayType) type;
            Type compType = gat.getGenericComponentType();

            // Resolve the raw class; if it cannot be resolved we fall back to Object.class.
            componentClass = (Class<?>) TypeUtils.getClass(compType);
        } else {
            // Expected to be a concrete array class (e.g. String[]).
            Class<?> arrayClass = (Class<?>) type;
            componentClass = arrayClass.getComponentType();
        }

        // -----------------------------------------------------------------
        // 4. Whitelist validation – reject any component type that is not
        //    explicitly allowed. This prevents deserialization of dangerous
        //    classes such as those that trigger RMI look‑ups.
        // -----------------------------------------------------------------
        if (componentClass == null) {
            throw new IllegalArgumentException("Unable to determine component type for: " + type);
