        // Primitive types are handled via their wrapper equivalents.
        if (componentClass.isPrimitive()) {
            componentClass = TypeUtils.getWrapper(componentClass);
        }

        if (!ALLOWED_COMPONENT_TYPES.contains(componentClass)
                && !componentClass.isEnum()
                && !componentClass.isArray()) {
            throw new IllegalArgumentException(
                    "Deserialization of component type '" + componentClass.getName()
                    + "' is not permitted for security reasons.");
        }

        // -----------------------------------------------------------------
        // 5. Parse the JSON array safely using the resolved component class.
        // -----------------------------------------------------------------
        JSONArray array = new JSONArray();
        parser.parseArray(componentClass, array, fieldName);

        // -----------------------------------------------------------------
        // 6. Convert the JSONArray into a native Java array.
        // -----------------------------------------------------------------
        return (T) toObjectArray(parser, componentClass, array);
    }

    // -----------------------------------------------------------------
    // Existing helper – unchanged (assumed to be safe). If it internally
    // uses Fastjson features that rely on auto‑type, the safe mode set above
    // will protect it.
    // -----------------------------------------------------------------
    private static Object toObjectArray(DefaultJSONParser parser, Class<?> componentType, JSONArray array) {
        // Simplified conversion – Fastjson already stores the parsed elements
        // as the correct Java type thanks to parseArray(componentClass,…).
        int size = array.size();
        Object result = java.lang.reflect.Array.newInstance(componentType, size);
        for (int i = 0; i < size; ++i) {
            java.lang.reflect.Array.set(result, i, array.get(i));
        }
        return result;
    }

    // other methods (serialize, etc.) remain unchanged
